def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt={}
    for r in range(H):
        for c in range(W):
            cnt[inp[r][c]]=cnt.get(inp[r][c],0)+1
    bg=max(cnt,key=cnt.get)
    seen=set(); comps=[]
    def bfs(seed):
        q=deque([seed]); comp={seed}; seen.add(seed)
        while q:
            x,y=q.popleft()
            for dx in(-1,0,1):
                for dy in(-1,0,1):
                    n=(x+dx,y+dy)
                    if 0<=n[0]<H and 0<=n[1]<W and inp[n[0]][n[1]]==inp[x][y] and n not in seen:
                        seen.add(n); q.append(n); comp.add(n)
        return comp
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and (r,c) not in seen:
                comps.append(bfs((r,c)))
    tot=sum(len(c) for c in comps)
    cy=sum(p[0] for c in comps for p in c)/tot
    cx=sum(p[1] for c in comps for p in c)/tot
    out=[row[:] for row in inp]
    for comp in comps:
        if len(comp)<2: continue
        v=inp[list(comp)[0][0]][list(comp)[0][1]]
        def dist(p): return abs(p[0]-cy)+abs(p[1]-cx)
        far=max(comp,key=dist)
        dr=1 if far[0]>cy else (-1 if far[0]<cy else 0)
        dc=1 if far[1]>cx else (-1 if far[1]<cx else 0)
        rr,cc=far
        while True:
            nr,nc=rr+dr,cc+dc
            if not(0<=nr<H and 0<=nc<W) or inp[nr][nc]!=bg: break
            out[nr][nc]=v; rr,cc=nr,nc
    return out
