def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    # 8-connected components of non-bg cells
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=set(); seen.add((r,c)); col=g[r][c]
                while st:
                    y,x=st.pop()
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dy==dx==0: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                comps.append(comp)
    gc_r=sum(r for r in range(H) for c in range(W) if g[r][c]!=bg)/sum(1 for r in range(H) for c in range(W) if g[r][c]!=bg)
    gc_c=sum(c for r in range(H) for c in range(W) if g[r][c]!=bg)/sum(1 for r in range(H) for c in range(W) if g[r][c]!=bg)
    out=[row[:] for row in g]
    def free(y,x): return 0<=y<H and 0<=x<W and g[y][x]==bg
    for comp in comps:
        m=max(( (p[0]-gc_r)**2+(p[1]-gc_c)**2 , p) for p in comp)
        far=m[1]
        # find diagonal stroke containing far, determine direction (away from centroid)
        found=False
        # try both diagonal directions from far; pick one that leads to free cell(s)
        for d in ((-1,-1),(-1,1),(1,-1),(1,1)):
            rr,cc=far[0]+d[0],far[1]+d[1]
            if free(rr,cc):
                # verify it's a diagonal continuation of the component
                ok=True
                rr2,cc2=far[0]-d[0],far[1]-d[1]
                if not (0<=rr2<H and 0<=cc2<W and g[rr2][cc2]==col): ok=False
                if ok:
                    found=True; step=d; break
        if not found: continue
        rr,cc=far[0]+step[0],far[1]+step[1]
        while free(rr,cc):
            out[rr][cc]=col; rr+=step[0]; cc+=step[1]
    return out

